// One Discord thread per card, so a card's completions stay together.
const threadName = 'Card: ' + $json.cardName;
const message = '\u2705 ' + $json.item + ' \u2014 completed by ' + $json.member + '\nhttps://trello.com/c/' + $json.cardShort;
return { json: { ...$json, threadName, message } };
